Bank.add("mna", [
  { id: "mna-01", lv: 2, q: "What does a material adverse change (MAC) clause in an acquisition agreement typically do?",
    o: ["Lets the buyer walk away if a major adverse event hits the target before completion", "Fixes the purchase price at signing, whatever happens to trading before completion", "Adjusts the adviser's success fee if the target's performance changes before completion", "Requires the seller to compensate the buyer if trading falls short of budget after completion"],
    why: "A MAC clause gives the buyer an exit if the target suffers a serious, lasting deterioration between signing and completion.",
    x: ["Price is set by the price mechanism (locked box or completion accounts), not a MAC clause.", "Adviser fees live in the engagement letter, not the purchase agreement.", "Post-completion shortfalls are handled by earn-outs or warranty claims; a MAC only applies before completion."] },
  { id: "mna-02", lv: 1, q: "What does a letter of intent (or term sheet) in an M&A deal typically do?",
    o: ["Sets out the price and structure, binding only on confidentiality and exclusivity", "Replaces the share purchase agreement in smaller deals, so no further contract is needed", "Transfers legal ownership of the shares to the buyer, subject only to regulatory approval", "Binds the buyer to complete at the stated price, whatever due diligence later finds"],
    why: "An LOI records the headline price and structure so both sides can commit to diligence. Usually only confidentiality, exclusivity and costs are binding.",
    x: ["Even small deals need a definitive purchase agreement; the LOI comes before it.", "Ownership passes at completion under the purchase agreement.", "Price stays subject to diligence; keeping the LOI non-binding is what allows that."] },
  { id: "mna-03", lv: 2, q: "A no-shop clause in a merger agreement is designed to:",
    o: ["Stop the target soliciting competing offers before the deal completes", "Stop the buyer reducing the agreed price after due diligence findings", "Require the target to keep trading with all of its existing suppliers", "Prevent the buyer financing the deal with new debt from other banks"],
    why: "A no-shop protects the buyer's time and money by stopping the target courting rival bidders, usually with a fiduciary out for superior offers.",
    x: ["Price changes are governed by price adjustment terms, not deal protection.", "Trading between signing and completion is covered by ordinary-course covenants.", "Financing is the buyer's choice; a no-shop restricts the seller."] },
  { id: "mna-04", lv: 2, trap: ["wrong-measure", null, "inverted"], q: "In an all-stock acquisition with no synergies, the deal is dilutive to the acquirer's EPS when:",
    o: ["The acquirer's P/E is lower than the P/E it pays for the target", "The acquirer's share price is higher than the target's", "The target has lower revenue than the acquirer", "The acquirer's P/E is higher than the P/E it pays for the target"],
    why: "Each new low-P/E share issued brings in less profit than the earnings it dilutes, so EPS falls.",
    x: ["The share price level doesn't matter; earnings per dollar of value (P/E) does.", "Relative size changes how big the effect is, not its direction.", "That's the accretive case: highly valued shares buying cheaper earnings."] },
  { id: "mna-05", lv: 2, q: "How does a locked box price mechanism work?",
    o: ["The price is fixed from a past balance sheet, and the seller promises no value has leaked since", "The price is adjusted after completion for actual net debt and working capital", "The whole price is held in escrow until regulators approve the deal, then released to the seller", "The shares are held by a trustee until the buyer's financing is confirmed by its banks"],
    why: "A locked box gives the seller price certainty. The buyer is protected by a promise of no 'leakage' (dividends, fees) after the locked box date.",
    x: ["That's the completion accounts mechanism, the main alternative.", "Escrows hold part of the price against claims; they aren't a price mechanism.", "Trustee arrangements aren't how either price mechanism works."] },
  { id: "mna-06", lv: 1, q: "What is an earn-out?",
    o: ["Part of the price that depends on the target's results after completion", "A fee paid to the bidder by the target if the deal fails before completion", "A bonus paid to the target's managers for staying on after completion", "A price cut agreed after due diligence turns up problems at the target"],
    why: "Earn-outs bridge valuation gaps: the seller gets more if the business hits agreed targets, typically over one to three years.",
    x: ["That's a break fee.", "That's a retention bonus.", "That's a price chip negotiated before signing."] },
  { id: "mna-07", lv: 2, q: "When is a target's break fee (termination fee) typically paid?",
    o: ["When the deal fails for set reasons, such as the board backing a rival offer", "When the advisers' work is complete and the deal has been signed by both sides", "When regulators review the deal and charge the parties for their merger filing", "When the buyer pays the price early, to compensate the target for lost interest"],
    why: "A break fee compensates the bidder for its time and costs if the target walks away. Some regimes, such as the UK Takeover Code, largely ban target break fees.",
    x: ["Fees on completion are adviser success fees.", "Regulators charge filing fees, not break fees.", "Payment timing has nothing to do with it."] },
  { id: "mna-08", lv: 2, q: "What is vendor due diligence (VDD)?",
    o: ["Diligence commissioned by the seller and shared with bidders", "Diligence done by the buyer's lawyers after the purchase agreement is signed", "The competition regulator's review of whether the deal harms competition", "Checks the seller runs on its advisers' independence before hiring them"],
    why: "VDD speeds up an auction: bidders rely on one seller-commissioned report, often with reliance letters, instead of each starting from scratch.",
    x: ["Buyer diligence happens before signing and is the buyer's own work.", "Regulatory review is merger control, not diligence.", "It's diligence on the target business, not the advisers."] },
  { id: "mna-09", lv: 1, q: "What is the usual order of a two-stage sell-side auction?",
    o: ["Teaser and NDA → information memorandum and indicative bids → data room → binding bids → signing", "Binding bids → teaser and NDA → data room and management meetings → information memorandum → signing", "Data room → teaser and NDA → binding bids → information memorandum and indicative bids → signing", "Teaser and NDA → signing → data room → binding bids → information memorandum"],
    why: "Sellers reveal more as the field narrows. Only a shortlist gets data room and management access before binding offers.",
    x: ["Binding bids come after diligence, not at the start.", "The data room opens to a shortlist after indicative bids, not first.", "The purchase agreement is signed at the end, once a binding bid is accepted."] },
  { id: "mna-10", lv: 2, q: "What are warranties in a share purchase agreement?",
    o: ["Seller's statements of fact about the business, giving a damages claim if untrue", "Promises by the buyer to keep all of the target's employees for a set period after completion", "The regulatory approvals that must be obtained before the deal can complete", "The formula used to calculate the final price from the completion accounts"],
    why: "Warranties cover things like accounts, litigation and tax. Claims are limited by caps, thresholds and what the seller disclosed.",
    x: ["Buyer promises are covenants, not seller warranties.", "Regulatory approvals are conditions to completion.", "The price formula sits in the consideration clauses."] },
  { id: "mna-11", lv: 3, q: "What does a disclosure letter do?",
    o: ["Lists exceptions to the seller's warranties, so disclosed matters can't ground a claim", "Announces the deal to the stock market, disclosing the price and the parties", "Records the regulator's decision on the deal and any conditions it has imposed", "Shows how the buyer is financing the deal, disclosing its banks and their terms"],
    why: "Sellers disclose heavily against warranties because fairly disclosed matters can't be the basis of a later claim.",
    x: ["Market announcements are separate documents.", "Regulators issue decisions, not disclosure letters.", "Financing is evidenced by commitment letters."] },
  { id: "mna-12", lv: 3, q: "What does warranty and indemnity (W&I) insurance cover?",
    o: ["The buyer's losses from breaches of the seller's warranties", "The target's employees after the deal, for injury and illness at work", "The risk of a regulator blocking the deal before it can complete", "The buyer's acquisition financing, if its banks pull out before completion"],
    why: "W&I lets the seller exit cleanly with a low liability cap while the buyer keeps recourse through an insurer. It's common in private equity exits.",
    x: ["Employee cover is ordinary insurance, unrelated to the deal.", "Regulatory risk is handled through conditions and reverse break fees.", "Financing risk isn't covered by W&I."] },
  { id: "mna-13", lv: 2, q: "Why is there often a gap of several months between signing and completion?",
    o: ["Conditions such as merger control approvals must be satisfied first", "The buyer still needs to agree the valuation with the seller's board", "The lawyers still need to draft and agree the letter of intent", "The terms must be renegotiated once the buyer has run its diligence"],
    why: "Between signing and completion the parties wait for conditions precedent such as antitrust, regulatory or shareholder approvals.",
    x: ["The valuation is agreed before signing.", "The LOI comes long before signing.", "Signing locks in the terms; renegotiation isn't the purpose of the gap."] },
  { id: "mna-14", lv: 1, q: "What makes a takeover bid 'hostile'?",
    o: ["It's made directly to shareholders without the support of the target's board", "It offers a premium of more than 50% over the target's undisturbed share price", "The bidder is a direct competitor that wants to remove the target from the market", "The target is in financial distress, so the bidder can force through a low price"],
    why: "A hostile bid goes over the board's head to shareholders, often with a tender offer or a proxy fight.",
    x: ["The premium size doesn't make a bid hostile.", "Competitors can make agreed bids too.", "Distress has nothing to do with hostility."] },
  { id: "mna-15", lv: 2, q: "What is a fairness opinion?",
    o: ["An adviser's view that the price is financially fair to shareholders", "A legal opinion that the deal is lawful and properly approved by the board", "The auditor's sign-off on the target's accounts used to set the price", "The regulator's approval of the price, after checking it against peers"],
    why: "Boards get fairness opinions to support their fiduciary duties when recommending or accepting an offer.",
    x: ["Legality is for lawyers, not a financial opinion.", "Auditors sign off accounts, not deal prices.", "Regulators don't opine on whether a price is fair."] },
  { id: "mna-16", lv: 2, q: "Which synergies do investors usually give more credit to, and why?",
    o: ["Cost synergies, because they are more within management's control", "Revenue synergies, because they are usually larger and grow over time", "Both equally, since each adds the same amount to profit in the end", "Neither, since synergies are never included in valuations"],
    why: "Cutting overlapping costs is quicker and more controllable than winning new revenue, which depends on customers' behaviour.",
    x: ["Bigger isn't more credible; revenue synergies are often heavily discounted.", "Markets clearly discount revenue synergies more.", "Credible synergies do get credit, especially cost ones."] },
  { id: "mna-17", lv: 3, q: "How does a tender offer differ from a merger?",
    o: ["The bidder buys shares directly from shareholders, who each decide whether to sell", "It needs no shareholder involvement, as the two boards agree it between them", "It's only used to buy private companies, whose few owners can be approached directly", "It must always be paid in the bidder's shares, never in cash"],
    why: "In a tender offer holders choose individually whether to tender; a merger is approved by a shareholder vote and binds everyone.",
    x: ["Shareholders decide individually, so they are very much involved.", "Tender offers are mainly for listed companies with dispersed shareholders.", "Consideration can be cash, shares or a mix."] },
  { id: "mna-18", lv: 2, trap: ["concept", "wrong-measure", "concept"], q: "How does a poison pill (shareholder rights plan) deter a hostile bidder?",
    o: ["Past a set ownership threshold, other holders can buy cheap shares, diluting the bidder", "It forces the target to take on heavy debt as soon as a bid is made, so it's less attractive", "It makes a bidder pay a fee to the target's board before it can make a bid", "It strips voting rights from any new shareholder above a set threshold"],
    why: "When a hostile bidder's stake crosses the trigger (often 10–20%), every other shareholder gets rights to buy shares at a discount. The bidder is diluted, so in practice it has to negotiate with the board, which can withdraw the pill. Pills are a US tool; under the UK Takeover Code a board can't take frustrating action without shareholder approval.",
    x: ["Loading up on debt is a different tactic (a leveraged recapitalisation), not a rights plan.", "There's no entry fee; the pill works by diluting the bidder.", "Voting rights aren't removed; the bidder's stake is diluted instead."] },
  { id: "mna-19", lv: 1, trap: ["inverted", "concept", "wrong-measure"], q: "In a hostile takeover, what is a 'white knight'?",
    o: ["A friendlier buyer the target invites to make a competing offer", "The hostile bidder, once the target's board recommends its offer", "A regulator that blocks the bid on competition grounds", "An investor that buys a minority stake to block the bid without taking control"],
    why: "A target facing an unwanted bid may find a preferred buyer, a white knight, to outbid the hostile one with better terms or friendlier plans for the business.",
    x: ["A hostile bid that the board comes to recommend simply becomes a friendly offer.", "Regulators can block deals, but they aren't called white knights.", "That's a white squire: a friendly investor taking a blocking stake rather than buying the whole company."] },
  { id: "mna-20", lv: 2, trap: ["inverted", "concept", "wrong-measure"], q: "What is the main difference between a spin-off and an equity carve-out?",
    o: ["A spin-off gives the unit's shares to the parent's holders; a carve-out sells shares for cash", "A spin-off sells the subsidiary for cash; a carve-out gives its shares to the parent's shareholders", "A spin-off is only for private companies; a carve-out is only for listed ones", "A carve-out sells the whole subsidiary; a spin-off sells only part of it"],
    why: "After a spin-off, existing shareholders own two separately listed companies and no cash changes hands. In an equity carve-out, the parent sells a stake, usually a minority, through an IPO, raising cash and keeping control. Selling the business outright to a buyer is a divestiture.",
    x: ["That's the wrong way round: it's the carve-out that raises cash.", "Both are used by listed groups; a carve-out usually involves an IPO.", "A carve-out usually sells a minority stake. Selling all of it is a divestiture."] },
  { id: "mna-21", lv: 3, trap: ["inverted", "concept", "concept"], q: "In a stock deal with a fixed exchange ratio, who bears the risk of the buyer's share price falling between signing and completion?",
    o: ["The target's shareholders, who get a set number of shares whatever they're worth", "The buyer's shareholders, because the buyer must issue more shares to make up the value", "Nobody, because the deal value is locked in at signing for both sides", "The target's lenders, whose loans are repaid in the buyer's shares at completion"],
    why: "A fixed ratio fixes the number of shares, so the value the target's holders receive moves with the buyer's share price, while the buyer knows its dilution exactly. A floating ratio fixes the value instead: if the buyer's price falls it issues more shares, so the buyer bears that risk.",
    x: ["That describes a floating ratio, where the value is fixed and the share count adjusts.", "Only the share count is locked; the value moves with the buyer's share price.", "Lenders are usually repaid or refinanced in cash; the price risk sits with the equity consideration."] },
  { id: "mna-22", lv: 3, trap: ["concept", "wrong-measure", "concept"], q: "What does a collar on a fixed exchange ratio do?",
    o: ["Adjusts the ratio if the buyer's share price leaves a set range, limiting value swings", "Caps how many of the target's shareholders can accept the offer before it finally closes", "Fixes the deal value at signing, whatever happens to either company's share price", "Lets the buyer switch from paying in shares to paying in cash at completion"],
    why: "Inside the range the ratio stays fixed and the value moves with the buyer's shares. Outside it, the ratio adjusts (or a party can walk away), so the price risk is shared between the buyer and the target's shareholders.",
    x: ["Acceptance levels are a separate offer condition, not a collar.", "That's a floating ratio. A collar only protects the value outside the agreed range.", "Changing the form of consideration needs a separate mechanism, such as a cash or share election."] },
  { id: "mna-23", lv: 2, trap: ["concept", "inverted", "concept"], q: "Why might a buyer choose to pay in shares rather than cash?",
    o: ["Its shares look richly valued, and the target's holders then share the deal risk", "Shares are always the cheaper currency for a buyer, because they never need repaying", "Paying in shares avoids diluting existing shareholders, unlike borrowing", "Stock deals never need shareholder approval, so they're quicker to complete"],
    why: "Paying in shares makes sense when the buyer's stock is expensive (a high P/E makes it a cheap currency) or when it wants the target's shareholders to stay exposed to whether the deal works. A buyer that thinks its shares are undervalued prefers cash and keeps all the upside.",
    x: ["Shares are cheap only when the buyer's P/E is high compared with what it pays; otherwise cash or debt costs less.", "Issuing shares dilutes existing holders' ownership; that's the main cost of paying in stock.", "Issuing many new shares often needs the buyer's shareholders to approve it (on the NYSE and Nasdaq, above 20% of existing shares)."] },
  { id: "mna-24", lv: 1, trap: ["wrong-measure", "sign", "missed-step"], q: "A buyer agrees to pay US$500m for a company on a cash-free, debt-free basis. At completion the company has US$80m of debt and US$30m of cash. Before any other adjustments, what does the seller receive for the shares?",
    o: ["US$450m", "US$500m", "US$550m", "US$420m"],
    why: "The headline price is an enterprise value that assumes no debt and no cash. The debt is repaid and the seller is credited for the cash: equity price = 500 − 80 + 30 = US$450m.",
    x: ["US$500m is the enterprise value. The debt must be repaid, and the cash credited, before the seller is paid.", "The signs are reversed: debt reduces the price and cash increases it.", "That deducts the debt but forgets to credit the US$30m of cash."] },
  { id: "mna-25", lv: 2, trap: ["inverted", "concept", "wrong-measure"], q: "A deal has a working capital peg of US$40m. At completion the target's working capital is US$34m. Under completion accounts, what happens to the price?",
    o: ["It falls by US$6m, the shortfall against the peg", "It rises by US$6m", "Nothing: working capital is part of the business being sold", "It falls by US$34m"],
    why: "The peg is the normal level of working capital the price assumes. A shortfall means the buyer must fund the gap, so the price falls dollar for dollar; an excess raises it. This stops a seller running down receivables or stretching payables just before completion.",
    x: ["The shortfall works against the seller, not for it.", "The peg exists precisely so that the price reflects a normal level of working capital.", "Only the difference from the peg is adjusted, not the whole balance."] },
  { id: "mna-26", lv: 2, trap: ["concept", "wrong-measure", "concept"], q: "Why might part of the purchase price be held in escrow after completion?",
    o: ["To give the buyer a ready source of payment for warranty or indemnity claims", "To pay the advisers' fees once the deal has completed and been signed off", "To fund the target's working capital needs in the months after completion", "To defer the seller's tax bill on its capital gain until the following tax year"],
    why: "An escrow, or a holdback by the buyer, keeps part of the price back for an agreed period. If a warranty or indemnity claim succeeds, the buyer is paid from it instead of chasing the seller. W&I insurance can reduce or replace it.",
    x: ["Advisers are paid separately, usually by the side that hired them.", "Working capital is dealt with through the peg or a locked box, not escrow.", "Escrow protects the buyer; tax timing isn't its purpose."] },
  { id: "mna-27", lv: 2, trap: ["concept", "inverted", "concept"], q: "What is the 'winner's curse' in a competitive auction?",
    o: ["The winner is likely the bidder that overestimated the asset's value the most", "The seller ends up accepting too low a price because bidders hold back", "The winner must pay back the losing bidders' costs of due diligence and advice", "The winning bid gets cut once due diligence starts and problems turn up"],
    why: "When bidders estimate the same uncertain value, the highest bid tends to come from the most optimistic estimate, so winning can mean overpaying. Disciplined buyers set a walk-away price before bidding.",
    x: ["Competition usually pushes the price up for the seller, not down.", "Losing bidders normally bear their own costs.", "Cutting a bid after exclusivity ('price chipping') is a different problem."] },
  { id: "mna-28", lv: 2, trap: ["inverted", "concept", "wrong-measure"], q: "After a US$50 per share cash offer is announced, the target's shares trade at US$46. What does the US$4 gap mainly reflect?",
    o: ["The risk that the deal fails, plus the time until completion", "The market expects a higher competing bid to arrive before completion", "The target's shares are simply mispriced, as markets often are", "Advisers' fees that will be deducted from the offer before payment"],
    why: "Merger arbitrageurs buy at 46 to receive 50 at completion. The spread pays them for the chance the deal breaks (regulators, financing, a shareholder vote) and for waiting. A price above the offer would instead suggest the market expects a higher bid.",
    x: ["Expecting a higher bid would push the price above the offer, not below it.", "Arbitrageurs trade the gap actively; it prices deal risk and time, not a simple error.", "Fees are paid by the companies, not deducted from shareholders' proceeds."] },
  { id: "mna-29", lv: 3, trap: ["inverted", "sign", "concept"], q: "In the purchase price allocation, a buyer writes up the target's customer relationships, a finite-life intangible, by US$100m. All else equal, what is the effect?",
    o: ["Goodwill is lower, and the extra amortisation reduces the buyer's future EPS", "Goodwill is higher, and EPS is unchanged because intangibles aren't expensed", "Goodwill is lower, and EPS rises because less goodwill has to be amortised each year", "Nothing: write-ups only affect the target's own accounts, not the buyer's"],
    why: "The price is fixed, so every dollar allocated to identifiable assets leaves less for goodwill (net of the deferred tax liability the write-up creates). Goodwill isn't amortised under IFRS 3, only tested for impairment, but a finite-life intangible is, so reported EPS falls.",
    x: ["Allocating more to identifiable assets leaves less for goodwill, not more, and the amortisation hits EPS.", "Goodwill isn't amortised in the first place; the new amortisation on the intangible lowers EPS.", "The allocation is made in the buyer's consolidated accounts."] },
  { id: "mna-30", lv: 2, trap: ["inverted", "concept", "concept"], q: "What is a reverse merger (reverse takeover)?",
    o: ["A private company lists by merging into a listed one, whose holders end up in the minority", "A listed company buys a private company and keeps control of the combined group", "A merger that is unwound after completion, with both companies returned to their original owners", "A target buying the company that bid for it, to defend itself against the bid"],
    why: "The listed company issues so many shares to the private company's owners that they take control. It's a route to a listing without a full IPO (SPAC mergers work in a similar way), and for accounting the private company is usually treated as the acquirer.",
    x: ["That's an ordinary acquisition. In a reverse merger the private company's owners end up in control.", "Unwinding a deal isn't a reverse merger.", "That's the Pac-Man defence."] },
  { id: "mna-31", lv: 2, trap: ["missed-step", "concept", "inverted"], q: "A buyer can pay for an acquisition with cash that earns 3% interest, new debt costing 6%, or new shares at a P/E of 20. The tax rate is 25%. In earnings-per-share terms, which order runs from cheapest to most expensive?",
    o: ["Cash (2.25% after tax), then debt (4.5% after tax), then shares (5%)", "Cash (3%), then shares (5%), then debt (6%)", "Shares first, because issuing them has no interest cost", "Debt (4.5% after tax), then cash (2.25% after tax), then shares (5%)"],
    why: "Each way to pay costs the buyer earnings. Cash: the interest it no longer earns, after tax: 3% × 0.75 = 2.25%. Debt: the interest it pays, after tax: 6% × 0.75 = 4.5%. Shares: the earnings that now go to new shareholders, the earnings yield 1 ÷ P/E = 1 ÷ 20 = 5%.",
    x: ["Interest is taxed (or tax-deductible), so compare after-tax costs: 2.25% and 4.5%, which puts debt ahead of shares.", "Shares have a cost too: the new holders take a share of all future earnings. That cost is the earnings yield, 1 ÷ P/E.", "That ranks debt ahead of cash, but 4.5% is more than 2.25%."] },
  { id: "mna-32", lv: 1, trap: ["concept", "concept", "concept"], q: "A car maker buys one of its tyre suppliers. What kind of merger is this, and what's the usual rationale?",
    o: ["Vertical: securing supply and keeping the supplier's margin in the group", "Horizontal: buying a competitor to gain market share and cut duplicated costs", "Conglomerate: diversifying into an unrelated business", "A reverse merger: the target ends up as the listed company"],
    why: "A vertical merger joins companies at different stages of the same supply chain. A horizontal merger joins competitors at the same stage. A conglomerate merger joins unrelated businesses.",
    x: ["A tyre supplier sells to the car maker; it doesn't compete with it. That's a different stage of the chain.", "Tyres are a direct input for cars, so the businesses are related, not unrelated.", "A reverse merger is a way for a private company to list by merging into a listed one. It says nothing about the businesses' relationship."] },
  { id: "mna-33", lv: 2, trap: ["concept", "concept", "concept"], q: "In a sell-side auction, when do potential buyers usually receive the information memorandum?",
    o: ["After signing a confidentiality agreement, before indicative offers are due", "Before signing anything, attached to the teaser that goes out to potential buyers", "Only after binding offers, together with access to the data room", "At signing, as a schedule to the share purchase agreement"],
    why: "The teaser is short and anonymous and goes to a wide list. Interested buyers sign a confidentiality agreement (NDA) and then receive the information memorandum: the business, its market, historical financials and the business plan. They base their indicative offers on it.",
    x: ["The information memorandum is confidential, so buyers sign an NDA first. The teaser is what goes out unsigned.", "It comes earlier. The data room and management meetings come in the second round, before binding offers.", "It's a marketing document for the first round, not a contract document."] },
  { id: "mna-34", lv: 2, trap: ["wrong-measure", "wrong-measure", "wrong-measure"], q: "What does a process letter set out in an M&A auction?",
    o: ["The rules of the round: the bid deadline and what an offer must contain", "The seller's warranties to the buyer and the limits on claims under them", "The company's business plan and historical financials for bidders to review", "The bank's fee and the scope of its mandate to run the sale"],
    why: "The seller's bank sends a process letter at each round. It sets the deadline, the format of offers and what they must cover (price and its basis, financing, conditions, approvals, due diligence still needed), and what happens next.",
    x: ["Warranties are in the share purchase agreement, with exceptions listed in the disclosure letter.", "That's the information memorandum.", "That's the engagement letter between the seller and its bank."] },
  { id: "mna-35", lv: 2, trap: ["wrong-measure", "concept", "concept"], q: "A bank is pitching to advise on the sale of a company. What does its pitch book usually contain?",
    o: ["Why this bank, its view of the company and value, likely buyers and a proposed process", "The detailed business plan and three years of audited accounts for buyers to review in diligence", "The draft share purchase agreement, with the bank's proposed price and terms", "A fairness opinion on the expected price, to reassure the board before the sale"],
    why: "A pitch book wins the mandate. It shows the bank understands the company and its market, who might buy it (or, for a buy-side pitch, which targets fit), what it might be worth, and how the bank would run the sale.",
    x: ["That's the information memorandum, prepared once the bank has been hired.", "Lawyers draft the share purchase agreement later in the process, once a buyer is chosen.", "A fairness opinion comes at the end, when a board approves a deal, and is often given by a bank that isn't running the sale."] },
  { id: "mna-36", lv: 2, trap: ["concept", "inverted", "concept"], q: "Why can a trade (strategic) buyer often pay more than a private equity buyer for the same company?",
    o: ["It can count on synergies, and doesn't need to hit a fund's target return in a few years", "It always borrows more, so its cost of capital is lower than a private equity fund's", "Private equity buyers can't use debt, so their equity cheques limit what they can pay", "Trade buyers don't need to do due diligence, so they save costs they can add to the price"],
    why: "A trade buyer values the target plus the synergies it brings to its own business, and it can hold forever. A private equity buyer values the company on its own, needs an exit in about 3–7 years, and works back from its target return to a maximum price.",
    x: ["Trade buyers usually use less debt than private equity buyers, not more. Their edge is synergies.", "It's the opposite: private equity relies heavily on debt (that's the leverage in a leveraged buyout).", "Every buyer does due diligence. Trade buyers often know the industry better, but that isn't why they can pay more."] },
  { id: "mna-37", lv: 2, trap: ["concept", "wrong-measure", "wrong-measure"], q: "In a merger of two listed companies, what does a contribution analysis compare?",
    o: ["Each side's share of combined revenue, EBITDA and profit with its share of the new group", "Each company's share price over the past year, to set the exchange ratio from the trend", "The synergies each management team expects to deliver once the deal has completed", "Each company's net assets at book value, which by law sets the split of ownership"],
    why: "It shows what each side brings. If a company contributes 40% of combined EBITDA but its shareholders would own only 30% of the group, they can argue for a better exchange ratio. It's a sense check rather than a valuation: it ignores differences in growth and risk, and where the two have different debt, EBITDA should be compared with each side's share of enterprise value, not of equity.",
    x: ["Share price history feeds a different analysis. Contribution looks at what each business earns.", "Synergies come from combining the two, so they can't be split by contribution.", "Book values don't set the ownership split. It's negotiated, and contribution is one input."] },
  { id: "mna-38", lv: 2, trap: ["concept", "concept", "inverted"], q: "A target has US$200m of unused tax losses, and the tax rate is 25%. Why might a buyer value them at well below US$50m?",
    o: ["Their use may be capped after a change of owner, and the savings come over years", "Tax losses are always cancelled in full when a company is bought by another", "The buyer has to pay tax on the losses at the moment it takes control", "The losses stay with the seller, who keeps their benefit after the sale"],
    why: "Losses only save tax when the company makes taxable profit, so US$200m × 25% = US$50m is the most they could save, spread over several years and worth less today. Many countries also restrict losses after a change of ownership: in the US, Section 382 caps how much can be used each year; the UK can disallow them if the business changes soon after the sale. Buyers value the savings they can actually use, discounted to today.",
    x: ["Not always cancelled: they usually survive, but often with limits on how fast they can be used.", "Taking control doesn't trigger tax on losses. The issue is whether they can still be used.", "In a share deal the losses stay with the company being bought, so they pass to the buyer with it."] },
  { id: "mna-39", lv: 2, trap: ["double-count", "missed-step", "wrong-measure"], q: "A buyer uses US$500m of its own cash to buy 100% of a target whose net assets are worth US$350m, at both book and fair value. How does the combined balance sheet differ from adding the two together?",
    o: ["The target's equity goes, the buyer's cash falls by US$500m and US$150m of goodwill is added", "Both companies' equity is kept, and US$500m of goodwill is added to the combined assets", "Nothing is taken out, and US$150m of goodwill is added on top of both balance sheets", "The target's assets are left out, and the US$500m is shown as a single investment"],
    why: "On consolidation, the buyer's investment is replaced by the target's assets and liabilities (at fair value), and the target's equity is eliminated: only the buyer's equity remains. Goodwill = price − fair value of net assets = 500 − 350 = US$150m. The buyer's cash falls by the US$500m it paid. The group still balances: net assets change by 350 + 150 − 500 = 0, and equity is unchanged.",
    x: ["Keeping the target's equity counts it twice: the buyer has paid for it. Goodwill is the excess over net assets, not the full price.", "The target's equity has to be eliminated and the cash paid taken out, or the balance sheet double counts.", "That's how the buyer's own (unconsolidated) accounts show it. A group with control consolidates line by line."] },
  { id: "mna-40", lv: 2, trap: ["concept", "concept", "sign"], q: "When working out the equity price of a takeover, why are the target's diluted shares calculated at the offer price rather than at its current share price?",
    o: ["Options are settled on the deal terms, so at the offer price more are in the money", "The current share price already includes the premium, so it would count it twice", "Accounting rules require using the highest share price of the last 12 months", "Using the offer price lowers the share count, which reduces the price to pay"],
    why: "Option holders are paid on the deal terms. At the higher offer price, more options are in the money and each is worth more, so the diluted share count, and the total equity price, both rise. Using the undisturbed share price would understate what the buyer pays.",
    x: ["The undisturbed share price has no premium in it. That's why it's used to measure the premium.", "No such rule exists. The offer price is used because it's what option holders will be paid on.", "It's the opposite: at a higher price more options count, so the share count rises."] },
  { id: "mna-41", lv: 2, trap: ["inverted", "concept", "concept"], q: "In a sale, the buyer pays part of the price with a vendor loan (seller note). Why might the seller agree to it?",
    o: ["It bridges a funding gap and can support a higher headline price", "It ranks ahead of the buyer's bank debt, so it's close to risk-free", "It's repaid in full at completion, so the seller takes no risk at all", "It turns the seller's stake into ordinary shares in the buyer's group"],
    why: "A vendor loan defers part of the price: the seller lends it to the buyer, to be repaid later with interest, usually ranking behind the bank debt. It helps when banks won't lend enough, signals the seller's confidence in the business, and can support a higher headline price. The cost is credit risk: if the business struggles, the seller may not be repaid in full.",
    x: ["Vendor loans usually rank behind the bank debt. Lenders insist on it.", "It's paid later, not at completion. That deferral is the point, and the risk.", "That's a rollover of equity. A vendor loan is debt owed to the seller."] },
  { id: "mna-42", lv: 1, trap: ["concept", "concept", "concept"], q: "Why might a target's shareholders prefer to be paid in cash rather than in the buyer's shares?",
    o: ["Cash fixes the value they receive, with no exposure to how the buyer does", "Shares are always taxed more heavily than cash when a company is taken over", "Cash offers always come with a higher premium than offers paid in shares", "Taking the buyer's shares would mean giving up their voting rights entirely"],
    why: "Cash locks in the value at completion. Shares leave them exposed to the buyer's share price and to whether the deal works, though they keep a slice of the upside and the synergies. Tax often points the other way: in many countries a share-for-share exchange can defer capital gains tax, while cash is taxed straight away.",
    x: ["Often it's the reverse: a share exchange can defer capital gains tax, while cash is taxed now.", "Premiums depend on the deal, not just on how it's paid.", "They receive voting shares in the buyer, just a smaller stake in a bigger company."] },
  { id: "mna-43", lv: 3, trap: ["concept", "concept", "inverted"], q: "A deal will add 5% to the buyer's earnings per share in its first year. Does that mean it creates value for the buyer's shareholders?",
    o: ["Not necessarily: EPS ignores whether the price paid exceeds what the target is worth", "Yes: higher EPS means a higher share price if the buyer's P/E stays the same", "Yes, as long as the deal is paid for entirely with new debt rather than with shares", "No: a deal that adds to EPS shows the buyer has overpaid for the target"],
    why: "Accretion only compares earnings per share before and after. Cheap debt makes almost any cash deal accretive, but it adds risk, so the buyer's P/E may fall. Value is created only if the target is worth more to the buyer (including synergies) than the price paid: compare the return on the money invested with its cost of capital.",
    x: ["The P/E rarely stays the same: more debt and a riskier group usually lower it.", "Debt funding often makes a deal accretive precisely because debt looks cheap in EPS terms, while its risk is ignored.", "Accretion says nothing about overpaying either way: a deal can add to EPS and still destroy value, or the reverse."] }
]);

// New-format questions (shown only when "new formats" is on). New IDs: the multiple-choice mna-09 above stays as it is.
Bank.addFormat("mna", [
  { id: "mna-ord-01", lv: 2, type: "order", q: "Put the stages of a two-stage sell-side M&A auction in order, first to last.",
    answer: ["Teaser and NDA", "Information memorandum", "Indicative bids", "Data room and management meetings", "Binding bids", "Signing the purchase agreement"],
    why: "Sellers reveal more as the field narrows. Only a shortlist gets data room and management access before binding offers, and the purchase agreement is signed once a binding bid is accepted." },
  { id: "mna-grid-01", lv: 2, type: "grid", q: "Takeover defences: is each one put in place before a bid arrives, or used after a bid is made?",
    columns: ["Before a bid", "After a bid"],
    rows: [
      { text: "Staggered (classified) board", answer: 0, note: "Only part of the board is elected each year, so a bidder can't replace it in one go." },
      { text: "Dual-class shares", answer: 0, note: "Founders keep voting control through shares that carry extra votes." },
      { text: "Golden parachutes", answer: 0, note: "Large payouts to managers on a change of control make a takeover more expensive." },
      { text: "White knight", answer: 1, note: "The target looks for a friendlier buyer once a hostile bid has been made." },
      { text: "Pac-Man defence", answer: 1, note: "The target turns round and bids for the bidder." },
      { text: "Selling the crown jewels", answer: 1, note: "The target sells the assets the bidder wants most." }
    ],
    why: "Preventive defences are built into the company's structure in advance; reactive ones respond to a bid that has arrived. Under the UK Takeover Code, a board can't take frustrating action once a bid is made without shareholder approval." },
  { id: "mna-grid-02", lv: 2, type: "grid", q: "Is each of these a spin-off, an equity carve-out or a divestiture?",
    columns: ["Spin-off", "Carve-out", "Divestiture"],
    rows: [
      { text: "The parent's shareholders receive the subsidiary's shares and no cash is raised", answer: 0, note: "Shares go to existing shareholders for nothing: a spin-off." },
      { text: "The parent sells a minority stake in the subsidiary through an IPO", answer: 1, note: "Selling shares to new investors while keeping control is a carve-out." },
      { text: "The parent sells the division to a private equity buyer for cash", answer: 2, note: "An outright sale to a buyer is a divestiture." },
      { text: "Afterwards, the parent's shareholders own two separately listed companies", answer: 0, note: "That's the result of a spin-off." },
      { text: "The parent raises cash but keeps control and still consolidates the subsidiary", answer: 1, note: "A carve-out raises cash and leaves the parent in control." },
      { text: "The parent no longer owns any of the business and keeps the sale proceeds", answer: 2, note: "The business has been sold: a divestiture." }
    ],
    why: "Spin-off: shares to existing shareholders, no cash. Carve-out: shares to new investors for cash, parent keeps control. Divestiture: the business is sold outright." },
  // Walk-through cards: answer out loud, then grade yourself against the model answer.
  { id: "mna-walk-01", lv: 2, type: "walk", q: "Walk me through an accretion/dilution analysis.",
    points: [
      "Start with the buyer's and the target's projected net income, and the buyer's share count and share price.",
      "Set the purchase price and how it's paid: new shares, cash on hand, new debt or a mix.",
      "Adjust combined net income: add synergies, subtract after-tax interest on new debt and the interest lost on cash used, and subtract amortisation of written-up intangibles.",
      "Add the new shares issued to the buyer's share count.",
      "Pro forma EPS = adjusted combined net income ÷ new share count. Above the buyer's standalone EPS is accretive; below is dilutive."
    ],
    why: "Mention the shortcut too: an all-stock deal is accretive when the buyer's P/E is above the P/E it pays. And say that accretion doesn't by itself mean the deal creates value." },
  { id: "mna-walk-02", lv: 1, type: "walk", q: "Walk me through a sell-side M&A process.",
    points: [
      "Preparation: hire advisers, prepare the information memorandum, a model and often vendor due diligence, and draw up a list of buyers.",
      "Marketing: send teasers, sign NDAs and send out the information memorandum.",
      "First round: buyers submit non-binding indicative bids, and the seller picks a shortlist.",
      "Second round: shortlisted buyers get data room access, management presentations and the draft purchase agreement, then submit binding bids with their mark-up.",
      "Negotiation, signing and completion: agree the purchase agreement with the preferred bidder, sign, then complete once regulatory and other conditions are met."
    ],
    why: "Show you know why it's staged: competition keeps price tension while information is released gradually to fewer, more serious buyers." },
  { id: "mna-grid-03", lv: 2, type: "grid", q: "In due diligence, which workstream would most likely find each issue?",
    columns: ["Financial", "Tax", "Legal", "Commercial"],
    rows: [
      { text: "EBITDA is flattered by one-off income booked last quarter", answer: 0, note: "The quality of earnings review strips out one-offs to find normal EBITDA." },
      { text: "Working capital was unusually low on the reference date", answer: 0, note: "Financial due diligence sets a normal level of working capital, which feeds the price." },
      { text: "Tax losses may be lost after the change of ownership", answer: 1, note: "Many countries limit the use of losses after a change of control (in the US, Section 382)." },
      { text: "A key customer contract can be ended if the company changes owner", answer: 2, note: "A change-of-control clause, found by reviewing material contracts." },
      { text: "A pending lawsuit over a faulty product", answer: 2, note: "Legal reviews litigation, permits and compliance." },
      { text: "The market is shrinking and a new competitor is winning share", answer: 3, note: "Commercial due diligence tests the market and the business plan's assumptions." }
    ],
    why: "Financial checks the numbers (normal earnings, net debt, working capital); tax checks past exposures and the deal's tax effects; legal checks contracts, disputes and compliance; commercial checks the market and the plan." },
  { id: "mna-grid-04", lv: 2, type: "grid", q: "Under IFRS, how is each cost of an acquisition accounted for?",
    columns: ["Expensed when incurred", "Spread over the debt's life", "Deducted from equity"],
    rows: [
      { text: "Financial adviser's fee for the acquisition", answer: 0, note: "IFRS 3 treats the costs of doing a deal as an expense of the period, not part of the price, so they don't add to goodwill." },
      { text: "Lawyers' fees for negotiating the share purchase agreement", answer: 0, note: "A cost of doing the deal, so it's expensed." },
      { text: "Arrangement fee on the term loan that funds the deal", answer: 1, note: "Under IFRS 9 it's deducted from the loan and spread over its life as part of the effective interest rate." },
      { text: "Due diligence costs", answer: 0, note: "A cost of doing the deal, so it's expensed, even if the work was done months before signing." },
      { text: "Underwriting fee on new shares issued to fund the deal", answer: 2, note: "Costs of issuing equity come off equity (IAS 32), not the income statement." },
      { text: "Original issue discount on a bond issued to fund the deal", answer: 1, note: "Like a fee, the discount is spread over the bond's life through the effective interest rate." }
    ],
    why: "Costs of doing the acquisition are expensed as incurred (IFRS 3). Costs of raising the money follow what was raised: debt costs reduce the debt and are spread over its life through the effective interest rate (IFRS 9), and equity issue costs come off equity (IAS 32). US GAAP is similar." }
]);

// More new formats: answer + reason and spot the error.
Bank.addFormat("mna", [
  { id: "mna-why-01", lv: 2, type: "reason",
    q: "A buyer trading on a P/E of 20x buys a target on a P/E of 12x, paying entirely in new shares. Ignoring synergies and fees, is the deal accretive or dilutive to the buyer's EPS?",
    answers: ["Accretive", "Dilutive", "Neither"],
    answerNotes: [
      "It would be dilutive if the target's P/E were above the buyer's. Here it's below.",
      "EPS changes whenever the earnings bought don't match, share for share, what the buyer's own shares earn."],
    reasons: [
      "It issues shares priced at 20x earnings to buy earnings priced at 12x",
      "Issuing new shares always dilutes the existing shareholders' earnings per share",
      "Without synergies there's no extra profit, so earnings per share can't change",
      "The target is cheaper, so the buyer gets a bargain and its share price rises"],
    reasonNotes: [
      "New shares dilute EPS only if the earnings they buy are too small. Here each new share brings in more earnings than an existing one earns.",
      "The target's profit is added. Whether EPS rises depends on that profit compared with the number of shares issued.",
      "Accretion is about earnings per share, not the share price, and a cheap purchase doesn't guarantee a higher price."],
    why: "In an all-share deal, compare P/Es. The buyer's shares are priced at 20x earnings, so each new share costs it 1/20 = 5% of its price in earnings. The target earns 1/12 ≈ 8.3% of its price. Buying 8.3% earnings with 5% earnings makes EPS rise, so the deal is accretive. On its own, accretion says nothing about whether the deal creates value." },

  { id: "mna-why-02", lv: 2, type: "reason",
    q: "A buyer and a seller disagree on a company's value: the seller expects strong growth, and the buyer doubts it. Which deal term best bridges the gap?",
    answers: ["An earn-out", "A larger escrow", "A break fee", "A locked box"],
    answerNotes: [
      "An escrow covers claims under the warranties, not whether the forecasts come true.",
      "A break fee applies if the deal fails. It doesn't settle a disagreement about value.",
      "A locked box fixes the price on past figures. It doesn't help when the disagreement is about future growth."],
    reasons: [
      "Part of the price is paid only if the growth actually happens",
      "Holding back more of the price protects the buyer if the forecasts are too high",
      "A break fee compensates the seller if the buyer walks away over the price",
      "Fixing the price on past accounts removes any argument about the future"],
    reasonNotes: [
      "Escrow protects against breaches of warranties, such as undisclosed liabilities, not against missed forecasts.",
      "That compensates for a failed deal. It doesn't help the two sides agree a price.",
      "Past accounts can't settle a disagreement about the future, which is what this is."],
    why: "An earn-out splits the price into a fixed part paid now and a part paid later only if the business hits agreed targets, such as revenue or EBITDA. The seller is paid for the growth it believes in, and the buyer only pays if it happens. The catch: disputes over how the targets are measured, and over how the buyer runs the business in the meantime." },

  { id: "mna-spot-01", lv: 2, type: "spot",
    q: "A buyer offers US$30 a share for a target whose undisturbed share price was US$24. The target has 50m diluted shares, US$300m of debt, US$100m of cash and EBITDA of US$170m. A candidate works out the premium and the implied multiple. Which line contains the mistake?",
    lines: [
      "Premium: (US$30 − US$24) ÷ US$24 = 25%",
      "Equity value at the offer: 50m × US$30 = US$1,500m",
      "Net debt: US$300m − US$100m = US$200m",
      "Enterprise value: US$1,500m − US$200m = US$1,300m",
      "EV/EBITDA: US$1,300m ÷ US$170m = about 7.6x"],
    wrong: 3,
    lineNotes: [
      "The premium is measured against the undisturbed price, so 25% is right.",
      "Offer price times diluted shares is right.",
      "Debt less cash gives net debt. That's right.",
      null,
      "Dividing by EBITDA is right, but it uses the wrong enterprise value from line 4."],
    fixes: [
      "Add net debt to the equity value: EV is US$1,700m, or 10.0x EBITDA",
      "Use the undisturbed US$24 price: EV is US$1,400m, or about 8.2x",
      "Add gross debt but ignore the cash: EV is US$1,800m, or about 10.6x",
      "Use basic shares instead of diluted ones, which lowers the equity value"],
    fixNotes: [
      "The buyer pays US$30, so the deal is valued at the offer price. The undisturbed price is only used to measure the premium.",
      "Cash is netted off: the buyer gets it along with the company.",
      "Diluted shares are right: option and convertible holders will be paid at the offer price too."],
    why: "Enterprise value = equity value + net debt: US$1,500m + US$200m = US$1,700m, or 10.0x EBITDA of US$170m. A buyer of the whole company takes on its debt and gets its cash, so net debt is added. Subtracting it makes the deal look cheaper than it is." },

  { id: "mna-why-03", lv: 2, type: "reason",
    q: "A buyer pays US$400m in cash for a debt-free target that earns net income of US$20m a year. It funds the price with new debt at 6% interest, and the tax rate is 25%. Ignoring fees and synergies, is the deal accretive or dilutive to the buyer's EPS?",
    answers: ["Accretive", "Dilutive", "Neither"],
    answerNotes: [
      "That compares pre-tax interest with after-tax earnings. Interest is tax-deductible, so it costs only US$18m after tax.",
      "Net income rises by 20 − 18 = US$2m on the same number of shares, so EPS rises."],
    reasons: [
      "The after-tax interest, US$18m, is less than the US$20m the target adds",
      "The pre-tax interest, US$24m, is more than the target's US$20m net income",
      "Deals funded with debt are always dilutive, because interest cuts net income",
      "No new shares are issued, so earnings per share cannot change at all"],
    reasonNotes: [
      "Interest is tax-deductible, so it costs 24 × (1 − 25%) = US$18m after tax. That's the figure to compare with net income.",
      "Only when the after-tax interest exceeds what the target earns. Here it doesn't.",
      "The share count is unchanged, but net income changes, so EPS does too."],
    why: "In a debt-funded deal, compare what the target adds to net income with the after-tax cost of the debt. Interest is US$400m × 6% = US$24m, or US$18m after 25% tax. The target adds US$20m, so the buyer's net income rises by US$2m with the same number of shares: the deal is accretive. In a real model, fees and extra depreciation from fair-value write-ups would also come in." },

  { id: "mna-spot-02", lv: 3, type: "spot",
    q: "A buyer pays US$800m for 100% of a target's shares. The target's net assets have a book value of US$500m, and the buyer writes up its intangible assets by US$120m. The tax rate is 25%. A candidate works out the goodwill. Which line contains the mistake?",
    lines: [
      "Price paid for 100% of the shares: US$800m",
      "Target's net assets at book value: US$500m",
      "Write-up of intangibles to fair value: US$120m",
      "Deferred tax on the write-up: none, as it's only an accounting entry",
      "Net assets at fair value: 500 + 120 = US$620m",
      "Goodwill: 800 − 620 = US$180m"],
    wrong: 3,
    lineNotes: [
      "The price is given in the question.",
      "The book value of net assets is given.",
      "Right: identifiable intangibles are recognised at fair value.",
      null,
      "The addition is right, but it leaves out the deferred tax from line 4.",
      "The subtraction is right, but it carries the mistake forward."],
    fixes: [
      "Deduct deferred tax of US$30m: net assets US$590m, goodwill US$210m",
      "Add deferred tax of US$30m: net assets US$650m, goodwill US$150m",
      "Deduct tax on all US$620m: US$155m, so goodwill is US$335m",
      "Ignore the write-up too: net assets US$500m, goodwill US$300m"],
    fixNotes: [
      "The write-up creates a liability (more tax later), so it lowers net assets, which raises goodwill.",
      "Only the write-up creates a new gap between book and tax values; the rest is already in the target's accounts.",
      "Identifiable intangibles must be recognised at fair value. Leaving them out overstates goodwill."],
    why: "In a share deal the target's tax values don't change, so writing its assets up in the accounts creates a gap between book and tax values: a deferred tax liability of 120 × 25% = US$30m. Net assets at fair value = 500 + 120 − 30 = US$590m, and goodwill = 800 − 590 = US$210m. (In an asset deal the tax values usually step up too, so no deferred tax arises.)" }
]);
